spec.query:
from(bucket: "robin-lorenz.de")
  |> range(start: -30d)
  |> filter(fn: (r) => r._measurement == "cloudflare_analytics_country")
  |> filter(fn: (r) => r._field == "requests")
  |> group(columns: ["country"])
  |> sum()
  |> map(fn: (r) => ({
      lookup: string(v: r.country),
      value: float(v: r._value)
  }))

from(bucket: "${bucket}")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "cloudflare_analytics")
  |> filter(fn: (r) => r._field == "cfRequestsAll" or r._field == "cfRequestsCached")
  |> map(fn: (r) => ({
      all: if r._field == "cfRequestsAll" then float(v: r._value) else 0.0,
      cached: if r._field == "cfRequestsCached" then float(v: r._value) else 0.0
  }))
  |> group()
  |> reduce(
      identity: {all: 0.0, cached: 0.0},
      fn: (r, accumulator) => ({
          all: accumulator.all + r.all,
          cached: accumulator.cached + r.cached
      })
  )
  |> map(fn: (r) => ({ _value: if r.all > 0.0 then r.cached / r.all * 100.0 else 0.0, metric: "Cache Hit Rate" }))
  |> keep(columns: ["_value", "metric"])

from(bucket: "${bucket}")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "cloudflare_analytics")
  |> filter(fn: (r) => r._field == "cfRequestsAll" or r._field == "cfEncryptedRequests")
  |> map(fn: (r) => ({
      all: if r._field == "cfRequestsAll" then float(v: r._value) else 0.0,
      encrypted: if r._field == "cfEncryptedRequests" then float(v: r._value) else 0.0
  }))
  |> group()
  |> reduce(
      identity: {all: 0.0, encrypted: 0.0},
      fn: (r, accumulator) => ({
          all: accumulator.all + r.all,
          encrypted: accumulator.encrypted + r.encrypted
      })
  )
  |> map(fn: (r) => ({ _value: if r.all > 0.0 then r.encrypted / r.all * 100.0 else 0.0, metric: "HTTPS Rate" }))
  |> keep(columns: ["_value", "metric"])

from(bucket: "${bucket}")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "cloudflare_analytics")
  |> filter(fn: (r) => r._field == "cfRequestsAll" or r._field == "cfThreatsAll")
  |> map(fn: (r) => ({
      requests: if r._field == "cfRequestsAll" then float(v: r._value) else 0.0,
      threats: if r._field == "cfThreatsAll" then float(v: r._value) else 0.0
  }))
  |> group()
  |> reduce(
      identity: {requests: 0.0, threats: 0.0},
      fn: (r, accumulator) => ({
          requests: accumulator.requests + r.requests,
          threats: accumulator.threats + r.threats
      })
  )
  |> map(fn: (r) => ({ _value: if r.requests > 0.0 then r.threats / r.requests * 1000.0 else 0.0, metric: "Threats / 1000 Requests" }))
  |> keep(columns: ["_value", "metric"])
